def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    try:
        # Basic sanity checks
        if not encoded or not original or not message:
            return "Failed"
        if len(encoded) != len(original):
            return "Failed"

        # Build mapping from encoded letter to original letter
        mapping = {}
        for e_char, o_char in zip(encoded, original):
            # Ensure both are alphabetic
            if not e_char.isalpha() or not o_char.isalpha():
                return "Failed"
            # Normalize to uppercase for consistency
            e_char = e_char.upper()
            o_char = o_char.upper()
            if e_char in mapping:
                if mapping[e_char] != o_char:
                    return "Failed"  # Contradiction
            else:
                mapping[e_char] = o_char

        # All 26 letters must be represented
        if len(mapping) != 26:
            return "Failed"

        # Decode the message
        decoded_chars = []
        for c in message:
            if not c.isalpha():
                return "Failed"
            c_up = c.upper()
            if c_up not in mapping:
                return "Failed"
            decoded_chars.append(mapping[c_up])

        return "".join(decoded_chars)
    except Exception:
        return "Failed"

def min_remaining_space(V: int, n: int, volumes: list) -> int:
    """
    Calculate the minimum remaining space in a box after trying to fit a number of items with given volumes.

    This function uses a dynamic programming approach to determine the maximum volume that can be occupied
    in the box by any subset of the given items. It then returns the difference between the box's total capacity
    and this maximum occupied volume, which is the minimum remaining space.

    Args:
    - V (int): The total capacity of the box.
    - n (int): The number of items to consider for packing into the box.
    - volumes (List[int]): A list of the volumes of the n items.

    Returns:
    - int: The minimum remaining space in the box after fitting the items.
    """
    # Basic validation and edge cases
    try:
        if V < 0:
            return 0
        if n <= 0 or not volumes:
            return max(0, V)
        # In case the provided list is shorter/longer than n, we only use the first n valid integers
        volumes_to_use = [v for v in volumes[:n] if isinstance(v, int) and v >= 0]
        if not volumes_to_use:
            return max(0, V)
    except Exception:
        return max(0, V)

    # DP array: dp[s] is True if a subset of items can achieve total volume s
    dp = [False] * (V + 1)
    dp[0] = True
    best_sum = 0

    for vol in volumes_to_use:
        if vol > V:
            continue
        # Traverse backwards to avoid reusing the same item
        for s in range(V, vol - 1, -1):
            if dp[s - vol]:
                dp[s] = True
                if s > best_sum:
                    best_sum = s
                    # Early exit if perfect fit found
                    if best_sum == V:
                        return 0

    # In case the best sum was not found inside the loop, recompute in case dp[best] is True
    for s in range(V, -1, -1):
        if dp[s]:
            best_sum = s
            break

    remaining = V - best_sum
    return remaining if remaining >= 0 else 0

def sort_students(student_scores):
    """Sort a list of students based on score criteria.

    Sorts first by total score descending, then by Chinese score descending,
    and finally by student number ascending if needed.

    Args:
        student_scores (list): A list of tuples, each defined as
                               (student_number, total_score, chinese_score).

    Returns:
        list: Sorted list of tuples according to the rules.

    Raises:
        TypeError: If `student_scores` is not a list.
        ValueError: If an element is not a tuple of three numeric values.
    """
    if not isinstance(student_scores, list):
        raise TypeError("student_scores must be a list")

    # Validate each item; store a copy with proper types for sorting
    validated = []
    for idx, item in enumerate(student_scores):
        if not isinstance(item, tuple):
            raise ValueError(f"Element at index {idx} is not a tuple")
        if len(item) != 3:
            raise ValueError(f"Element at index {idx} does not contain 3 values")
        sn, total, chinese = item
        try:
            sn_int = int(sn)
        except Exception:
            raise ValueError(f"Student number at index {idx} must be convertible to int")
        try:
            total_num = float(total)
        except Exception:
            raise ValueError(f"Total score at index {idx} must be numeric")
        try:
            chinese_num = float(chinese)
        except Exception:
            raise ValueError(f"Chinese score at index {idx} must be numeric")
        validated.append((sn_int, total_num, chinese_num))

    # Perform sorting
    try:
        sorted_list = sorted(
            validated,
            key=lambda t: (-t[1], -t[2], t[0])
        )
    except Exception as e:
        raise ValueError(f"Error during sorting: {e}") from e

    return sorted_list
